window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-1f14409bfe400f9e"]={"versions": [{"id": "FIG-1f14409bfe400f9e", "releases": ["R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Aktivitätsdiagramm (<em>Activity Diagram</em>) mit Kontrollfluss, Entscheidungsrauten (<em>Decision Nodes</em>), Aktionsknoten (<em>Action Nodes</em>) sowie Start- und Endknoten.</li>\n<li><strong>Funktionale Einordnung:</strong> AUTOSAR Classic Platform, BSW-Modul <code>FrTSyn</code> (FlexRay Time Synchronization, standardisiert nach CP R23-11).</li>\n<li><strong>Technischer Zweck:</strong> Spezifikation des deterministischen Validierungsalgorithmus für den Sequenzzähler (<em>Sequence Counter</em>, SC) empfangener Time-Sync-Nachrichten auf Empfängerseite (FrTSyn Slave). Ziel ist die Erkennung von Nachrichtenverlusten, Duplikaten, Replay-/Stuck-Fehlern und die kontrollierte Wiedereinschwingung (<em>Hysterese</em>) nach einem Timeout-Zustand.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Ausführende Entität:</strong> <code>FrTSyn</code> RX-Pfad (Verarbeitung eingehender Global-Time-PDUs via PduR / FrIf).</li>\n<li><strong>Konfigurationsparameter (AUTOSAR BSW Module Configuration):</strong></li>\n<li><code>FrTSynGlobalTimeSequenceCounterJumpWidth</code> (uint8): Maximal zulässige Differenz zwischen zwei aufeinanderfolgenden Sequenzzählern. Ein Wert von <code>0</code> deaktiviert die Sprungweitenprüfung vollständig.</li>\n<li><code>FrTSynGlobalTimeSequenceCounterHysteresis</code> (uint8): Schwellwert aufeinanderfolgender valider Zählersprünge, die nach einem eingetretenen Timeout verifiziert werden müssen, bevor der Zeitstempel als synchronisationsgültig akzeptiert wird.</li>\n<li><strong>Laufzeit-Statusvariablen & Eingangsgrößen:</strong></li>\n<li>$SC(n)$: Sequenzzähler der aktuell empfangenen Nachricht (Extraktion aus PDU-Header).</li>\n<li>$SC(n-1)$: Gespeicherter Sequenzzähler der zuletzt verarbeiteten Nachricht.</li>\n<li><code>TIMEOUT bit</code>: Status-Flag, das anzeigt, ob zwischenzeitlich ein Empfangs-Timeout für die Synchronisations-PDU aufgetreten ist.</li>\n<li><code>Valid sequence counter (SC) jumps count</code>: Modulinterner Akkumulator zur Hysterese-Überwachung im Timeout-Erholungszustand.</li>\n<li><strong>Ergebniszustände (Aktionen):</strong></li>\n<li><code>Sequence Counter is valid</code> $\\rightarrow$ Nachricht wird für die lokale Uhrensynchronisation / Zeitfortschreibung freigegeben.</li>\n<li><code>Sequence Counter is not valid</code> $\\rightarrow$ Nachricht wird verworfen; keine Zeitkorrektur über diesen Frame.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der Algorithmus evaluiert bei jedem PDU-Empfang folgenden Entscheidungsbaum:</p>\n<ol class=\"fig-list\">\n<li><strong>Startup-Prüfung (<code>SWS_FrTSyn_00162</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><em>Bedingung:</em> <code>First Message after Startup?</code></li>\n<li><em>Pfad <code>[yes]</code>:</em> Keine Historie verfügbar $\\rightarrow$ Status unmittelbar <code>Sequence Counter is valid</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Feature-Aktivierung (<code>SWS_FrTSyn_00163</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><em>Bedingung:</em> <code>Sequence Counter Jump Width Check enabled?</code> (<code>FrTSynGlobalTimeSequenceCounterJumpWidth &gt; 0</code>).</li>\n<li><em>Pfad <code>[no]</code>:</em> Prüfung deaktiviert $\\rightarrow$ Status unmittelbar <code>Sequence Counter is valid</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Zweigaufspaltung anhand des Timeout-Status:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Normalbetrieb (<code>TIMEOUT bit == 0</code> / Kein Timeout aktiv):</strong></li>\n<li>Auswertung (<code>SWS_FrTSyn_00164</code>):</li>\n</ul>\n<p class=\"fig-p\">$$\\big(SC(n) - SC(n-1) > 0\\big) \\;\\land\\; \\big(SC(n) - SC(n-1) \\le \\text{FrTSynGlobalTimeSequenceCounterJumpWidth}\\big)$$</p>\n<p class=\"fig-p\"><em>(unter Berücksichtigung des Modulo-Überlaufs des Zählers)</em>.</p>\n<ul class=\"fig-list\">\n<li><code>[yes]</code> $\\rightarrow$ <code>Sequence Counter is valid</code>.</li>\n<li><code>[no]</code> $\\rightarrow$ <code>Sequence Counter is not valid</code> (z. B. Duplikat $\\Delta = 0$ oder Überschreitung der Sprungweite).</li>\n<li><strong>Wiederanlauf nach Timeout (<code>TIMEOUT bit == 1</code>):</strong></li>\n<li><strong>Stuck-Counter-Check (<code>SWS_FrTSyn_00165</code>):</strong></li>\n<li>$SC(n) - SC(n-1) == 0$ $\\rightarrow$ <code>[yes]</code>: Zähler hängt $\\rightarrow$ <code>Valid sequence counter (SC) jumps count = 0</code> $\\rightarrow$ weiter zur Hystereseprüfung.</li>\n<li><strong>Initialer Timeout-Wiedereintritt (<code>SWS_FrTSyn_00166</code>):</strong></li>\n<li>Erste Nachricht nach Timeout mit nicht-statischem Zähler $\\rightarrow$ <code>[yes]</code>: <code>Valid sequence counter (SC) jumps count = 1</code>.</li>\n<li><strong>Fortlaufende Hystereseakkumulation (<code>SWS_FrTSyn_00167</code>):</strong></li>\n<li>$SC(n) - SC(n-1) \\le \\text{FrTSynGlobalTimeSequenceCounterJumpWidth}$:</li>\n<li><code>[yes]</code> $\\rightarrow$ Inkrementierung: <code>Valid sequence counter (SC) jumps count++</code>.</li>\n<li><code>[no]</code> $\\rightarrow$ Sprungweite verletzt: Rücksetzen <code>Valid sequence counter (SC) jumps count = 0</code>.</li>\n<li><strong>Hysterese-Verifikation (<code>SWS_FrTSyn_00168</code>):</strong></li>\n<li>Bedingung: <code>Valid sequence counter (SC) jumps count &lt; FrTSynGlobalTimeSequenceCounterHysteresis + 1</code></li>\n<li><code>[yes]</code> (noch innerhalb der Hysterese): <code>Sequence Counter is not valid</code>.</li>\n<li><code>[no]</code> (genügend konsekutive valide Inkremente erreicht): <code>Sequence Counter is valid</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Terminierung:</strong> Zusammenführung beider Resultatspfade im Final Node.</li>\n</ol>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Modulo-Arithmetik beachten:</strong> Die Differenzberechnung $SC(n) - SC(n-1)$ muss im Treiber/Stack als Ringspeicher-/Modulo-Operation über die konfigurierte Bitbreite des Sequenzzählers implementiert werden (Wrap-Around-Robustheit).</li>\n<li><strong>Reset-Bedingungen für <code>TIMEOUT bit</code>:</strong> Das <code>TIMEOUT bit</code> darf erst nach erfolgreichem Durchlaufen der Hysterese (<code>Sequence Counter is valid</code>) zurückgesetzt werden. Andernfalls schlägt der Schutzmechanismus fehl.</li>\n<li><strong>Konfigurations-Interdependenzen:</strong></li>\n<li>Ein zu klein konfigurierter <code>FrTSynGlobalTimeSequenceCounterJumpWidth</code> führt bei normalem FlexRay-Bus-Jitter oder zulässigen Frame-Ausfällen zu fälschlichem Verwerfen gültiger Synchronisationsframes.</li>\n<li><code>FrTSynGlobalTimeSequenceCounterHysteresis</code> bestimmt direkt die Einschwingzeit (<em>Recovery Time</em>) der globalen Zeitbasis nach Kommunikationsausfällen; Entwickler müssen diesen Wert gegen funktionale ASIL-Timing-Budgets (FTTI) abgleichen.</li>\n<li><strong>Fehlerbehandlung:</strong> Validierungsfehler führen nach <code>SWS_FrTSyn_00048</code> zur Nicht-Übernahme des Zeitstempels in die lokale Uhr, lösen jedoch keinen unmittelbaren DEM-Eintrag aus, solange die Time-Tracking-/Sync-Loss-Limits des Stacks (<code>StbM</code>) nicht verletzt werden.</li>\n</ul>"}, {"id": "FIG-06afbf8a99ee1807", "releases": ["R24-11", "R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Aktivitätsdiagramm (<em>Activity Diagram</em>) mit Kontrollfluss, Entscheidungsrauten (<em>Decision Nodes</em>), Aktionsknoten (<em>Action Nodes</em>) sowie Start- und Endknoten.</li>\n<li><strong>Funktionale Einordnung:</strong> AUTOSAR Classic Platform, BSW-Modul <code>FrTSyn</code> (FlexRay Time Synchronization, standardisiert nach CP R23-11).</li>\n<li><strong>Technischer Zweck:</strong> Spezifikation des deterministischen Validierungsalgorithmus für den Sequenzzähler (<em>Sequence Counter</em>, SC) empfangener Time-Sync-Nachrichten auf Empfängerseite (FrTSyn Slave). Ziel ist die Erkennung von Nachrichtenverlusten, Duplikaten, Replay-/Stuck-Fehlern und die kontrollierte Wiedereinschwingung (<em>Hysterese</em>) nach einem Timeout-Zustand.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Ausführende Entität:</strong> <code>FrTSyn</code> RX-Pfad (Verarbeitung eingehender Global-Time-PDUs via PduR / FrIf).</li>\n<li><strong>Konfigurationsparameter (AUTOSAR BSW Module Configuration):</strong></li>\n<li><code>FrTSynGlobalTimeSequenceCounterJumpWidth</code> (uint8): Maximal zulässige Differenz zwischen zwei aufeinanderfolgenden Sequenzzählern. Ein Wert von <code>0</code> deaktiviert die Sprungweitenprüfung vollständig.</li>\n<li><code>FrTSynGlobalTimeSequenceCounterHysteresis</code> (uint8): Schwellwert aufeinanderfolgender valider Zählersprünge, die nach einem eingetretenen Timeout verifiziert werden müssen, bevor der Zeitstempel als synchronisationsgültig akzeptiert wird.</li>\n<li><strong>Laufzeit-Statusvariablen & Eingangsgrößen:</strong></li>\n<li>$SC(n)$: Sequenzzähler der aktuell empfangenen Nachricht (Extraktion aus PDU-Header).</li>\n<li>$SC(n-1)$: Gespeicherter Sequenzzähler der zuletzt verarbeiteten Nachricht.</li>\n<li><code>TIMEOUT bit</code>: Status-Flag, das anzeigt, ob zwischenzeitlich ein Empfangs-Timeout für die Synchronisations-PDU aufgetreten ist.</li>\n<li><code>Valid sequence counter (SC) jumps count</code>: Modulinterner Akkumulator zur Hysterese-Überwachung im Timeout-Erholungszustand.</li>\n<li><strong>Ergebniszustände (Aktionen):</strong></li>\n<li><code>Sequence Counter is valid</code> $\\rightarrow$ Nachricht wird für die lokale Uhrensynchronisation / Zeitfortschreibung freigegeben.</li>\n<li><code>Sequence Counter is not valid</code> $\\rightarrow$ Nachricht wird verworfen; keine Zeitkorrektur über diesen Frame.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der Algorithmus evaluiert bei jedem PDU-Empfang folgenden Entscheidungsbaum:</p>\n<ol class=\"fig-list\">\n<li><strong>Startup-Prüfung (<code>SWS_FrTSyn_00162</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><em>Bedingung:</em> <code>First Message after Startup?</code></li>\n<li><em>Pfad <code>[yes]</code>:</em> Keine Historie verfügbar $\\rightarrow$ Status unmittelbar <code>Sequence Counter is valid</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Feature-Aktivierung (<code>SWS_FrTSyn_00163</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><em>Bedingung:</em> <code>Sequence Counter Jump Width Check enabled?</code> (<code>FrTSynGlobalTimeSequenceCounterJumpWidth &gt; 0</code>).</li>\n<li><em>Pfad <code>[no]</code>:</em> Prüfung deaktiviert $\\rightarrow$ Status unmittelbar <code>Sequence Counter is valid</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Zweigaufspaltung anhand des Timeout-Status:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Normalbetrieb (<code>TIMEOUT bit == 0</code> / Kein Timeout aktiv):</strong></li>\n<li>Auswertung (<code>SWS_FrTSyn_00164</code>):</li>\n</ul>\n<p class=\"fig-p\">$$\\big(SC(n) - SC(n-1) > 0\\big) \\;\\land\\; \\big(SC(n) - SC(n-1) \\le \\text{FrTSynGlobalTimeSequenceCounterJumpWidth}\\big)$$</p>\n<p class=\"fig-p\"><em>(unter Berücksichtigung des Modulo-Überlaufs des Zählers)</em>.</p>\n<ul class=\"fig-list\">\n<li><code>[yes]</code> $\\rightarrow$ <code>Sequence Counter is valid</code>.</li>\n<li><code>[no]</code> $\\rightarrow$ <code>Sequence Counter is not valid</code> (z. B. Duplikat $\\Delta = 0$ oder Überschreitung der Sprungweite).</li>\n<li><strong>Wiederanlauf nach Timeout (<code>TIMEOUT bit == 1</code>):</strong></li>\n<li><strong>Stuck-Counter-Check (<code>SWS_FrTSyn_00165</code>):</strong></li>\n<li>$SC(n) - SC(n-1) == 0$ $\\rightarrow$ <code>[yes]</code>: Zähler hängt $\\rightarrow$ <code>Valid sequence counter (SC) jumps count = 0</code> $\\rightarrow$ weiter zur Hystereseprüfung.</li>\n<li><strong>Initialer Timeout-Wiedereintritt (<code>SWS_FrTSyn_00166</code>):</strong></li>\n<li>Erste Nachricht nach Timeout mit nicht-statischem Zähler $\\rightarrow$ <code>[yes]</code>: <code>Valid sequence counter (SC) jumps count = 1</code>.</li>\n<li><strong>Fortlaufende Hystereseakkumulation (<code>SWS_FrTSyn_00167</code>):</strong></li>\n<li>$SC(n) - SC(n-1) \\le \\text{FrTSynGlobalTimeSequenceCounterJumpWidth}$:</li>\n<li><code>[yes]</code> $\\rightarrow$ Inkrementierung: <code>Valid sequence counter (SC) jumps count++</code>.</li>\n<li><code>[no]</code> $\\rightarrow$ Sprungweite verletzt: Rücksetzen <code>Valid sequence counter (SC) jumps count = 0</code>.</li>\n<li><strong>Hysterese-Verifikation (<code>SWS_FrTSyn_00168</code>):</strong></li>\n<li>Bedingung: <code>Valid sequence counter (SC) jumps count &lt; FrTSynGlobalTimeSequenceCounterHysteresis + 1</code></li>\n<li><code>[yes]</code> (noch innerhalb der Hysterese): <code>Sequence Counter is not valid</code>.</li>\n<li><code>[no]</code> (genügend konsekutive valide Inkremente erreicht): <code>Sequence Counter is valid</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Terminierung:</strong> Zusammenführung beider Resultatspfade im Final Node.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Modulo-Arithmetik beachten:</strong> Die Differenzberechnung $SC(n) - SC(n-1)$ muss im Treiber/Stack als Ringspeicher-/Modulo-Operation über die konfigurierte Bitbreite des Sequenzzählers implementiert werden (Wrap-Around-Robustheit).</li>\n<li><strong>Reset-Bedingungen für <code>TIMEOUT bit</code>:</strong> Das <code>TIMEOUT bit</code> darf erst nach erfolgreichem Durchlaufen der Hysterese (<code>Sequence Counter is valid</code>) zurückgesetzt werden. Andernfalls schlägt der Schutzmechanismus fehl.</li>\n<li><strong>Konfigurations-Interdependenzen:</strong></li>\n<li>Ein zu klein konfigurierter <code>FrTSynGlobalTimeSequenceCounterJumpWidth</code> führt bei normalem FlexRay-Bus-Jitter oder zulässigen Frame-Ausfällen zu fälschlichem Verwerfen gültiger Synchronisationsframes.</li>\n<li><code>FrTSynGlobalTimeSequenceCounterHysteresis</code> bestimmt direkt die Einschwingzeit (<em>Recovery Time</em>) der globalen Zeitbasis nach Kommunikationsausfällen; Entwickler müssen diesen Wert gegen funktionale ASIL-Timing-Budgets (FTTI) abgleichen.</li>\n<li><strong>Fehlerbehandlung:</strong> Validierungsfehler führen nach <code>SWS_FrTSyn_00048</code> zur Nicht-Übernahme des Zeitstempels in die lokale Uhr, lösen jedoch keinen unmittelbaren DEM-Eintrag aus, solange die Time-Tracking-/Sync-Loss-Limits des Stacks (<code>StbM</code>) nicht verletzt werden.</li>\n</ul>"}], "trans": [{"from": "FIG-1f14409bfe400f9e", "to": "FIG-06afbf8a99ee1807", "fr": "R23-11", "tr": "R24-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
